// Validate the webhook payload and build ONE safe shell command.
// Body: { id: "absence-request", youtube_url?: "https://...", recipe?: {...}, lang?, audience?, title?, upload?: true, dry_run?: true }
const REPO = '/opt/hackaton'; // <-- absolute path of the hackaton repo ON THE N8N HOST
const b = $input.first().json.body ?? $input.first().json;
if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]{0,80}$/.test(b.id ?? '')) throw new Error('invalid or missing id');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'"; // POSIX single-quote escaping
const out = REPO + '/out/' + b.id;
let pre = '';
const args = ['run', '--id', q(b.id)];
if (b.youtube_url) {
  if (!/^https:\/\/(www\.)?(youtube\.com|youtu\.be)\//.test(b.youtube_url)) throw new Error('youtube_url must be a YouTube URL');
  args.push('--youtube', q(b.youtube_url));
}
if (b.recipe) {
  const b64 = Buffer.from(JSON.stringify(b.recipe)).toString('base64'); // base64 alphabet is shell-safe
  const f = REPO + '/out/_incoming/' + b.id + '.recipe.json';
  pre = 'mkdir -p ' + q(REPO + '/out/_incoming') + ' && echo ' + b64 + ' | base64 -d > ' + q(f) + ' && ';
  args.push('--recipe', q(f));
}
for (const k of ['lang', 'audience', 'title']) if (b[k]) args.push('--' + k, q(b[k]));
if (b.upload) args.push('--upload');
if (b.dry_run) args.push('--dry-run');
const cmd =
  'cd ' + q(REPO) + ' && ' + pre +
  'pnpm --silent pipeline ' + args.join(' ') + ' >/dev/null 2>&1; ' +   // run (exit code ignored; state.json is the truth)
  'pnpm --silent pipeline status --id ' + q(b.id) + ' --json; ' +
  "echo; echo '---REVIEW---'; cat " + q(out + '/scenario.review.md') + ' 2>/dev/null || true';
return [{ json: { id: b.id, outDir: out, cmd } }];

// stdout = <state.json>\n---REVIEW---\n<review.md?>
const r = $input.first().json;
const meta = $('Build command').first().json;
const [jsonPart, review = ''] = String(r.stdout ?? '').split('---REVIEW---');
let state = null;
try { state = JSON.parse(jsonPart); } catch (e) {}
const stages = state ? Object.entries(state.stages) : [];
const failed = stages.find(([, s]) => s.status === 'failed');
const summary = stages.map(([k, s]) => k + ':' + s.status).join('  ');
return [{ json: {
  id: meta.id,
  outDir: meta.outDir,
  ok: !!state && !failed && state.stages.mux.status === 'done',
  videoUrl: state?.video_url ?? null,
  failedStage: failed?.[0] ?? null,
  failedSteps: state?.failed_steps ?? [],
  error: failed?.[1]?.error ?? (state ? null : 'could not read pipeline state: ' + (r.stderr || r.stdout || '').slice(0, 500)),
  summary,
  review: review.trim().slice(0, 2500),
} }];

